def semver_sort(versions):
    def parse_version(v):
        # Split off build metadata (everything after '+')
        if '+' in v:
            v, _ = v.split('+', 1)

        # Split core version from pre-release (everything after '-')
        if '-' in v:
            core, prerelease = v.split('-', 1)
        else:
            core = v
            prerelease = None

        # Parse MAJOR.MINOR.PATCH
        parts = core.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        prerelease_ids = []
        if prerelease is not None:
            prerelease_ids = prerelease.split('.')

        return (major, minor, patch, prerelease_ids)

    def compare_prerelease(pre1, pre2):
        # No pre-release (release version) sorts after pre-release
        if not pre1 and not pre2:
            return 0
        if not pre1:
            return 1
        if not pre2:
            return -1

        # Compare identifiers left to right
        for i in range(min(len(pre1), len(pre2))):
            id1 = pre1[i]
            id2 = pre2[i]

            is_num1 = id1.isdigit()
            is_num2 = id2.isdigit()

            if is_num1 and is_num2:
                # Both numeric: compare numerically
                cmp = int(id1) - int(id2)
                if cmp != 0:
                    return -1 if cmp < 0 else 1
            elif is_num1:
                # Numeric sorts before non-numeric
                return -1
            elif is_num2:
                # Non-numeric sorts after numeric
                return 1
            else:
                # Both non-numeric: compare by ASCII order
                if id1 < id2:
                    return -1
                elif id1 > id2:
                    return 1

        # If all shared identifiers are equal, fewer sorts first
        if len(pre1) < len(pre2):
            return -1
        elif len(pre1) > len(pre2):
            return 1
        else:
            return 0

    def sort_key(v):
        major, minor, patch, prerelease_ids = parse_version(v)

        # Return tuple for sorting
        # (major, minor, patch, prerelease_comparison_tuple)
        # For prerelease: if empty list (no prerelease), sort after
        # We use a tuple where (0, ...) is before (1, ...)
        if prerelease_ids:
            prerelease_tuple = (0, tuple(
                (0, int(x)) if x.isdigit() else (1, x)
                for x in prerelease_ids
            ))
        else:
            prerelease_tuple = (1,)  # No prerelease sorts after

        return (major, minor, patch, prerelease_tuple)

    # Use stable sort to preserve input order for equal versions
    return sorted(versions, key=sort_key)

